static void (*const fff_out_tab[8])(const int8_t *restrict, int32_t *restrict) = {
    fff_out0, fff_out1, fff_out2, fff_out3, fff_out4, fff_out5, fff_out6, fff_out7};

// fff_hn: ReLU + dynamic power-of-two requantization to 0..127, 12 values
static inline void fff_hn(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 12; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 12; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fff: fast feedforward tree (idea B): depth 3, 8 leaves of 12 neurons, 320 -> 64.
// The path takes 3 routing dot products; then only the reached leaf runs: 320 -> 12 (relu_norm) -> 64.
static void fff(const int8_t *restrict in, int32_t *restrict out) {
    int n = 0;
    for (int m = 0; m < 3; m++) n = 2 * n + (fff_node(in, (1 << m) - 1 + n) >= 0);
    fff_in_tab[n](in, fff_h);
    fff_hn(fff_h, fff_h8);
    fff_out_tab[n](fff_h8, out);
}

// norm2: ReLU + dynamic power-of-two requantization to 0..127, 64 values
static inline void norm2(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 64; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 64; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

